import {prerequisiteOrder} from './learning-core.js';
export const cityStorageKey='devops-city-explore-v1';
// Each of the 30 authored courses has one distinct discovery landmark.
export const topicLandmarks={practices:'developer',linux:'linux-host',networking:'load-balancer',scripting:'shell',git:'git',builds:'docker-build',cicd:'ci',testing:'unit-tests',artifacts:'artifact-store',containers:'docker-engine',kubernetes:'worker-a',iac:'terraform',configuration:'ansible',cloud:'compute',releases:'release-gate',gitops:'argocd','app-infrastructure':'redis',databases:'database',observability:'prometheus',incidents:'incident',sre:'slo',devsecops:'trivy',identity:'iam-city',recovery:'restore',platform:'platform-portal',finops:'cost',governance:'policy-code',serverless:'serverless',specialized:'aws-eks',documentation:'audit'};
export const hiddenTopics=['observability','iac','configuration','devsecops','serverless','finops','governance'];
export function emptyCityProgress(){return {version:1,discovered:[],lastConcept:'practices',started:false,towns:{},view:'3d'};}
export function parseCityProgress(raw,courses,nodes,flows){const clean=emptyCityProgress();try{const d=JSON.parse(raw);if(d?.version!==1)return clean;const ids=new Set(courses.map(c=>c.id));clean.discovered=[...new Set((Array.isArray(d.discovered)?d.discovered:[]).filter(id=>ids.has(id)))];if(ids.has(d.lastConcept))clean.lastConcept=d.lastConcept;clean.started=d.started===true;if(d.view==='2d')clean.view='2d';for(const [id,r]of Object.entries(d.towns||{})){if(!nodes.some(n=>n.id===id&&n.district)&&id!=='environment')continue;if(!r||typeof r!=='object'||!flows[r.flowId])continue;clean.towns[id]={flowId:r.flowId,step:Number.isInteger(r.step)?Math.max(0,Math.min(flows[r.flowId].steps.length-1,r.step)):0,selected:nodes.some(n=>n.id===r.selected)?r.selected:id};}return clean;}catch{return clean;}}
export function discoverTopics(state,nodeIds){const found=new Set(nodeIds),newIds=Object.entries(topicLandmarks).filter(([topic,node])=>found.has(node)&&!state.discovered.includes(topic)).map(([id])=>id);return {state:{...state,discovered:[...state.discovered,...newIds]},newIds};}
export function learningOrder(courses){return prerequisiteOrder(courses);}
export function installBeginnerFlows(nodes,flows,profiles,courses){const result={};const parentTown=id=>{let n=nodes.find(n=>n.id===id);while(n&&!n.district)n=nodes.find(p=>p.id===n.parent);return n?.id;};for(const c of courses){const primary=topicLandmarks[c.id],town=parentTown(primary),source=flows[profiles[town].flowId];let ids,steps,layout;if(c.id==='kubernetes'){ids=['worker-a','pod-a','app-a'];steps=flows['learn-k8s-inside'].steps;layout={'worker-a':[0,.7,0]};}else{const near=source.steps.filter(s=>s.from===primary||s.to===primary);ids=[...new Set([primary,...near.flatMap(s=>[s.from,s.to])])].slice(0,4);steps=source.steps.filter(s=>ids.includes(s.from)&&ids.includes(s.to));if(!steps.length){const p=nodes.find(n=>n.id===primary),sibling=nodes.find(n=>n.parent===p.parent&&n.id!==primary&&!n.minor);ids=[p.parent,primary,...(sibling?[sibling.id]:[])];steps=ids.slice(1).map(id=>({from:p.parent,to:id,title:'Find this component in its town',relation:'containment',channel:'logical',kind:'Containment · not network traffic',packet:'Logical grouping · no transport port',transport:null,exchange:null,text:nodes.find(n=>n.id===id).purpose}));}else if(ids.length<3){const candidate=source.steps.find(s=>ids.includes(s.from)&&!ids.includes(s.to)||ids.includes(s.to)&&!ids.includes(s.from));if(candidate){ids=[...new Set([...ids,candidate.from,candidate.to])].slice(0,4);steps=source.steps.filter(s=>ids.includes(s.from)&&ids.includes(s.to));}}if(ids.length<3){const parent=nodes.find(n=>n.id===ids.at(-1))?.parent;if(parent&&!ids.includes(parent)){const child=ids.at(-1);ids.push(parent);steps=[...steps,{from:parent,to:child,title:'Inspect the containing component',relation:'containment',channel:'logical',kind:'Containment · not network traffic',transport:null,exchange:null,packet:'Logical grouping · no transport port',text:'This arrow shows containment, not application forwarding.'}];}}layout={};ids.forEach((id,i)=>layout[id]=[-8+i*5.5,.9,i%2?2:-2]);}
 const flowId='beginner-'+c.id;flows[flowId]={label:'Beginner · '+c.title,color:0x76dfff,steps};result[c.id]={id:'beginner',topic:c.id,town,label:c.title,flowId,nodeIds:ids,overview:ids,layout,colors:{traffic:0x6be5ff,control:0xffa7b3,logical:0xffcd81,delivery:0xc5a0fa,images:0x6be5ff,telemetry:0x8fdfaa,storage:0x8fdfaa}};}return result;}
export function shortLabel(n){const descriptions={service:'finds eligible app Pods',ingress:'routes web requests',prometheus:'pulls metrics',terraform:'plans infrastructure',ansible:'configures hosts',registry:'stores images',ci:'coordinates builds','docker-engine':'runs containers',git:'versions code','worker-a':'hosts Pods','pod-a':'groups containers','app-a':'runs the app',etcd:'stores cluster state',scheduler:'chooses a worker'};return n.label+(descriptions[n.id]?' — '+descriptions[n.id]:'');}

export function scanTopicNodes(progress,nodes){const entries=Object.entries(topicLandmarks).map(([id,node])=>{let n=nodes.find(n=>n.id===node),x=0,z=0;while(n){x+=n.position[0];z+=n.position[2];n=nodes.find(p=>p.id===n.parent);}return {id,node,distance:Math.hypot(x,z)};});const radius=Math.max(...entries.map(e=>e.distance))*Math.max(0,Math.min(1,progress));return entries.filter(e=>e.distance<=radius).map(e=>e.node);}
